"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["81139"],{14287(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_cascata_remanejamento.fallback_obrigatorio","status":422,"titulo":"O c\xf3digo de fallback \xe9 obrigat\xf3rio e precisa casar com o vocabul\xe1rio de modalidade"},"descricao":{"codigo":"uniplus.selecao.configuracao_cascata_remanejamento.fallback_obrigatorio","requisitos":["UNI-REQ-0056"],"oQueAconteceu":["`fallbackCodigo` est\xe1 ausente, vazio, fora do vocabul\xe1rio\\n`^[A-Z][A-Z0-9]*(_[A-Z0-9]+)*$` ou excede 60 caracteres \u2014 o mesmo formato de c\xf3digo de\\nmodalidade usado no resto do m\xf3dulo, e a mesma confer\xeancia que\\n[`codigo_invalido`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.codigo_invalido)\\naplica a cada origem/destino, mas para o campo `fallbackCodigo`.","O fallback \xe9 a modalidade de ampla concorr\xeancia que recebe a vaga quando\\nnenhum destino da fila de remanejamento de uma origem est\xe1 selecionado na\\noferta em quest\xe3o \u2014 o \\"fim de linha\\" da cascata. Sem ele declarado, a\\ncascata n\xe3o tem para onde encaminhar uma vaga que a fila inteira n\xe3o\\nresolveu.","\xc9 a primeira confer\xeancia dentro da valida\xe7\xe3o de forma da cascata \u2014 roda antes\\nde qualquer confer\xeancia sobre os destinos. Acumula (ADR-0125), mas o conjunto\\nde causas com que pode coexistir muda conforme a lista `destinos` estiver\\nvazia ou n\xe3o:","- Lista vazia: s\xf3 pode coexistir com\\n  [`sem_destinos`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.sem_destinos)\\n  \u2014 sem nenhum destino, n\xe3o h\xe1 origem para verificar limite nem ordem.\\n- Lista n\xe3o vazia, todos os itens v\xe1lidos: pode coexistir com\\n  [`excede_limite_de_origens`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.excede_limite_de_origens),\\n  [`excede_limite_de_destinos`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.excede_limite_de_destinos),\\n  [`ordem_duplicada_na_origem`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.ordem_duplicada_na_origem),\\n  [`ordem_nao_contigua`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.ordem_nao_contigua)\\n  e\\n  [`destino_duplicado`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.destino_duplicado)\\n  \u2014 nunca com `sem_destinos`.\\n- Lista n\xe3o vazia, algum item inv\xe1lido: acumula com as causas de item e,\\n  no m\xe1ximo, com `excede_limite_de_origens`/`excede_limite_de_destinos` \u2014\\n  ver\\n  [`campos_obrigatorios`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.campos_obrigatorios)\\n  para o detalhe dessa composi\xe7\xe3o alternativa.","Na leitura da configura\xe7\xe3o publicada, este erro pode ocorrer quando `fallbackCodigo` est\xe1 vazio ou fora dos valores aceitos. Se a chave estiver ausente ou tiver mais de 60 caracteres, a leitura \xe9 recusada antes como `envelope_codec.envelope_malformado`. A leitura para na primeira viola\xe7\xe3o."],"comoResolver":["Informe `fallbackCodigo` casando com `^[A-Z][A-Z0-9]*(_[A-Z0-9]+)*$`, com no m\xe1ximo 60\\ncaracteres \u2014 o c\xf3digo de uma modalidade de ampla concorr\xeancia que de fato\\nest\xe1 selecionada nas ofertas que a cascata cobre."],"ondeAparece":["Defini\xe7\xe3o de cascata de remanejamento do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao cascata remanejamento"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);